  function c4svg(lv, sel) {
    const by = Object.fromEntries(lv.nodes.map(n => [n.id, n]));
    const clip = (n, tx, ty) => { const cx = n.x + n.w / 2, cy = n.y + n.h / 2, dx = tx - cx, dy = ty - cy; if (!dx && !dy) return { x: cx, y: cy }; const s = Math.min((n.w / 2 + 3) / Math.abs(dx || 1e-9), (n.h / 2 + 3) / Math.abs(dy || 1e-9)); return { x: cx + dx * s, y: cy + dy * s }; };
    let s = `<svg viewBox="0 0 ${lv.W} ${lv.H}" width="100%" style="min-width:${Math.min(lv.W, 640)}px;max-width:${lv.W}px" role="img" aria-label="${esc(lv.t)}"><defs><marker id="adc-ar" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10 z" style="fill:var(--text-2)"/></marker></defs>`;
    if (lv.bound) { const b = lv.bound; s += `<rect x="${b[0]}" y="${b[1]}" width="${b[2]}" height="${b[3]}" rx="12" style="fill:none;stroke:var(--border-strong);stroke-dasharray:6 5"/><text x="${b[0] + 12}" y="${b[1] + b[3] - 10}" style="fill:var(--text-muted);font-size:12px;font-weight:600">${esc(b[4])}</text>`; }
    lv.edges.forEach(([a, b, t]) => {
      const A = by[a], B = by[b];
      const p = clip(A, B.x + B.w / 2, B.y + B.h / 2), q = clip(B, A.x + A.w / 2, A.y + A.h / 2);
      const hot = sel && (a === sel || b === sel);
      s += `<line x1="${p.x}" y1="${p.y}" x2="${q.x}" y2="${q.y}" style="stroke:${hot ? 'var(--accent)' : 'var(--text-muted)'};stroke-width:${hot ? 2 : 1.3}" marker-end="url(#adc-ar)"/>`;
      if (t) s += `<text x="${(p.x + q.x) / 2}" y="${(p.y + q.y) / 2 - 4}" text-anchor="middle" style="fill:var(--text-2);font-size:11px;paint-order:stroke;stroke:var(--code-bg);stroke-width:4px;stroke-linejoin:round">${esc(t)}</text>`;
    });
    lv.nodes.forEach(n => {
      const on = n.id === sel;
      s += `<g data-node="${n.id}"><rect x="${n.x}" y="${n.y}" width="${n.w}" height="${n.h}" rx="${n.kind === 'person' ? 22 : n.kind === 'db' ? 14 : 9}" style="fill:${KIND[n.kind]};stroke:${on ? 'var(--accent)' : n.kind === 'ext' ? 'var(--border-strong)' : 'var(--border-strong)'};stroke-width:${on ? 2.6 : 1.2};${n.kind === 'ext' ? 'stroke-dasharray:5 4;' : ''}"/>`;
      s += `<text x="${n.x + n.w / 2}" y="${n.y + n.h / 2 - (n.sub ? 3 : -4)}" text-anchor="middle" style="fill:var(--text);font-size:${n.w < 140 ? 12 : 13}px;font-weight:600">${n.kind === 'person' ? '👤 ' : ''}${esc(n.t)}</text>`;
      if (n.sub) s += `<text x="${n.x + n.w / 2}" y="${n.y + n.h / 2 + 13}" text-anchor="middle" style="fill:var(--text-muted);font-size:11px">${esc(n.sub)}</text>`;
      s += '</g>';
    });
    return s + '</svg>';
  }
